module TopModule (
  input clk,
  input reset,
  input j,
  input k,
  output out
);

  localparam OFF = 1'b0, ON = 1'b1;
  reg state, next;

  always @(*) begin
    case (state)
      OFF: next = j ? ON : OFF;
      ON:  next = k ? OFF : ON;
      default: next = OFF;
    endcase
  end

  always @(posedge clk) begin
    if (reset) state <= OFF;
    else       state <= next;
  end

  assign out = (state == ON);

endmodule

module TopModule (
  input clk,
  input reset,
  input j,
  input k,
  output out
);

  localparam OFF = 1'b0, ON = 1'b1;
  reg state, next;
  // k has priority over j

  always @(*) begin
    case (state)
      OFF: next = (j & ~k) ? ON : OFF;
      ON:  next = k ? OFF : ON;
      default: next = OFF;
    endcase
  end

  always @(posedge clk) begin
    if (reset) state <= OFF;
    else       state <= next;
  end

  assign out = (state == ON);

endmodule

